{
  "critique": [
    {
      "design": "r0A",
      "good": "Host, role, zone, CPU and status values stay on one line, making ordinary rows compact and comparisons easy. The wider Notes column gives the long operational explanation a readable measure.",
      "problems": "The initial viewport cuts through Status and leaves Notes offscreen, separating the degraded indicator from its explanation. The tall note row also creates a large vertical gap before the remaining servers.",
      "cause": "The first four columns consume 319px, so the 88px Status column extends beyond the viewport; the 180px Notes column begins farther right. Its long content determines the degraded row's height."
    },
    {
      "design": "r0B",
      "good": "All headers stay intact, and Status fits within the initial viewport. Role, CPU and status values are easy to compare without mid-word splits.",
      "problems": "Host identifiers and zones break across lines, making routine rows much taller and harder to scan. Notes starts beyond the viewport and is so narrow that the degraded row becomes exceptionally tall.",
      "cause": "The 70px Host and 60px Zone columns force wraps at hyphens. Notes has only 64px of content width, producing a 29-line note."
    },
    {
      "design": "r0C",
      "good": "The whole table fits in the viewport, so status and its note are visible together without horizontal scrolling.",
      "problems": "Several headers, identifiers, roles and status values split inside words. This damages the column hierarchy and makes ordinary rows difficult to scan, while the long note still produces a very tall row.",
      "cause": "The 55px Host, 58px Role, 43px CPU and 66px Status widths leave too little content space for their longest words. The 82px Notes column leaves only 61px for text."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-scroll",
      "widths": [70, 80, 80, 53, 88, 200],
      "change": "Keep host identifiers and role and status words intact, allow zones to wrap at hyphens, and widen Notes for a shorter, more readable explanation. Status begins within the viewport but needs a small horizontal scroll to read fully."
    },
    {
      "name": "status-first",
      "widths": [70, 80, 60, 53, 88, 180],
      "change": "Keep all five inventory and health columns within the initial viewport, accepting natural zone wraps. Give Notes a generous width so the explanation is readable after scrolling."
    },
    {
      "name": "compact-note",
      "widths": [70, 80, 60, 53, 88, 120],
      "change": "Test a middle ground with Status visible initially and less horizontal travel to Notes. The note will wrap more than in the other proposals, but substantially less than in r0B."
    }
  ]
}
